import pytest
from microprotein_lm.gap_metrics import reconstruction, TrainingPositionSupport, translate_gap


def test_translation_uses_correct_internal_genetic_code():
    assert translate_gap('UGAAGAAGGAUA', 1) == '*RRI'
    assert translate_gap('UGAAGAAGGAUA', 2) == 'W**M'
    assert translate_gap('GUG', 2) == 'V'  # internal alternative start is not methionine


def test_reconstruction_keeps_exact_span_and_synonymous_error_distinct():
    result = reconstruction('AAUGAAUGA', 'AACGAAAGA', 2)
    assert result['exact_span'] == 0
    assert result['correct_codons'] == 1
    assert result['correct_amino_acids'] == 2
    assert result['synonymous_errors'] == 1
    assert result['has_premature_stop'] == 1
    assert result['first_error_codon'] == 1
    assert result['codon_matches'] == [0, 1, 0]
    assert result['amino_acid_matches'] == [1, 1, 0]
    with pytest.raises(ValueError):
        reconstruction('AAA', 'AAAAAA', 1)


def test_minority_support_is_not_saturated_variable_position_mask():
    rows = [{'family': 'X', 'tax_id': 1, 'rna': r} for r in
            ['AUGAAAUAA', 'AUGAAAUAA', 'AUGAACUAA']]
    support = TrainingPositionSupport(rows)
    minority = support.describe(rows[0], 1, 'AACUAG', 'AACUAA')
    assert minority['codon_support_labels'] == ['observed_minority', 'unobserved_codon']
    assert minority['training_support']['observed_minority']['correct_codons'] == 1
    other = support.describe({'family': 'X', 'tax_id': 2}, 1, 'AAA', 'AAA')
    assert other['family_seen'] and not other['taxon_seen']
    assert other['codon_support_labels'] == ['unsupported_position']


def test_tied_training_modes_are_all_majority():
    support = TrainingPositionSupport([{'family': 'X', 'tax_id': 1, 'rna': r}
                                        for r in ['AUGAAA', 'AUGAAC']])
    for truth in ['AAA', 'AAC']:
        result = support.describe({'family': 'X', 'tax_id': 1}, 1, truth, truth)
        assert result['codon_support_labels'] == ['majority']


def test_calculate_shannon_entropy_and_conservation_score():
    from microprotein_lm.gap_metrics import calculate_shannon_entropy, calculate_conservation_score
    from collections import Counter

    # Single allele => 0 entropy, max conservation 1.0
    single = Counter({'AUG': 10})
    assert calculate_shannon_entropy(single) == 0.0
    assert calculate_conservation_score(single, max_classes=64) == 1.0

    # Two equal alleles => 1.0 bit entropy
    equal = Counter({'AUG': 5, 'AAA': 5})
    assert abs(calculate_shannon_entropy(equal) - 1.0) < 1e-6
    assert 0.0 < calculate_conservation_score(equal, max_classes=64) < 1.0

    # Empty counts => 0.0 entropy, 1.0 conservation
    assert calculate_shannon_entropy(Counter()) == 0.0
    assert calculate_conservation_score(Counter(), max_classes=64) == 1.0


def test_msa_conservation_support():
    from microprotein_lm.gap_metrics import MSAConservationSupport

    records = [
        {'family': 'ATP8', 'tax_id': 9606, 'rna': 'AUGAAACUUUAA', 'translation_table': 2},
        {'family': 'ATP8', 'tax_id': 9913, 'rna': 'AUGAAACUGUAA', 'translation_table': 2},
    ]
    msa = MSAConservationSupport(records)
    res = msa.describe_msa(records[0], start=1, truth='AAACUU', prediction='AAACUG')

    assert res['msa_family'] == 'ATP8'
    assert len(res['msa_codon_entropies']) == 2
    assert res['msa_codon_entropies'][0] == 0.0  # AAA is conserved in both
    assert res['msa_consensus_codons'][0] == 'AAA'
    assert res['msa_is_consensus_match'] == [True, True]
    assert 0.0 <= res['mean_msa_codon_conservation'] <= 1.0


def test_domain_boundary_support_and_coordinate_features():
    from microprotein_lm.gap_metrics import DomainBoundarySupport

    record = {
        'family': 'ATP8',
        'rna': '.py',
        'translation_table': 2
    }
    support = DomainBoundarySupport()
    boundaries = support.describe_domain_boundaries(record, start=1, gap_codons=4)

    assert boundaries['has_domain_annotation'] is True
    assert boundaries['annotated_domains'][0]['domain_id'] == 'IPR001421'
    assert boundaries['is_inside_domain'] is True
    assert boundaries['distance_to_domain_start'] == 1
    assert boundaries['domain_overlap_type'] == 'fully_inside_domain'
    assert len(boundaries['per_codon_in_domain']) == 4
    assert all(boundaries['per_codon_in_domain'])


def test_training_position_support_integration():
    rows = [{'family': 'ATP8', 'tax_id': 9606, 'rna': 'AUGAAACUUUAA', 'translation_table': 2}]
    support = TrainingPositionSupport(rows)
    desc = support.describe(rows[0], 1, 'AAACUU', 'AAACUG')

    # Base features present
    assert desc['family_seen'] is True
    assert desc['taxon_seen'] is True
    assert desc['codon_support_labels'] == ['majority', 'majority']
    # MSA features present
    assert desc['msa_family'] == 'ATP8'
    assert 'msa_codon_entropies' in desc
    assert desc['mean_msa_codon_conservation'] == 1.0
    # Domain boundary coordinate features present
    assert desc['has_domain_annotation'] is True
    assert desc['is_inside_domain'] is True
    assert desc['domain_ids'] == ['IPR001421']

